import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"第 4 课：准备工作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-2/lesson-4.md","filePath":"modules/module-2/lesson-4.md"}'),l={name:"modules/module-2/lesson-4.md"};function d(s,t,h,i,n,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="第-4-课-准备工作" tabindex="-1">第 4 课：准备工作 <a class="header-anchor" href="#第-4-课-准备工作" aria-label="Permalink to &quot;第 4 课：准备工作&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：了解使用 Codex 前需要准备的账号、设备和网络环境<br> ⏱️ <strong>预计时长</strong>：10 分钟<br> 🎯 <strong>本节节奏</strong>：讲解为主</p></blockquote><hr><h2 id="一、你需要什么" tabindex="-1">一、你需要什么？ <a class="header-anchor" href="#一、你需要什么" aria-label="Permalink to &quot;一、你需要什么？&quot;">​</a></h2><h3 id="_1-一个-chatgpt-账号" tabindex="-1">1. 一个 ChatGPT 账号 <a class="header-anchor" href="#_1-一个-chatgpt-账号" aria-label="Permalink to &quot;1. 一个 ChatGPT 账号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>版本</th><th>价格</th><th>额度</th><th>推荐度</th></tr></thead><tbody><tr><td>免费版</td><td>¥0</td><td>有限额度</td><td>可以体验，但不够用</td></tr><tr><td>Plus</td><td>$20/月</td><td>充足</td><td>✅ 推荐入门</td></tr><tr><td>Pro</td><td>$200/月</td><td>大量</td><td>重度使用者</td></tr></tbody></table><blockquote><p>💡 <strong>建议</strong>：如果你是第一次接触，先用 Plus 版体验一周。如果觉得有用再决定是否升级 Pro。</p></blockquote><h3 id="_2-一台电脑" tabindex="-1">2. 一台电脑 <a class="header-anchor" href="#_2-一台电脑" aria-label="Permalink to &quot;2. 一台电脑&quot;">​</a></h3><ul><li><strong>macOS</strong>：macOS 12.0 及以上</li><li><strong>Windows</strong>：Windows 10 及以上</li><li><strong>Chromebook</strong>：支持 Chrome OS 即可</li></ul><h3 id="_3-稳定的网络连接" tabindex="-1">3. 稳定的网络连接 <a class="header-anchor" href="#_3-稳定的网络连接" aria-label="Permalink to &quot;3. 稳定的网络连接&quot;">​</a></h3><p>Codex 需要实时联网与 AI 服务器通信，建议使用 50Mbps 以上的宽带。</p><hr><h2 id="二、codex-的四种使用方式" tabindex="-1">二、Codex 的四种使用方式 <a class="header-anchor" href="#二、codex-的四种使用方式" aria-label="Permalink to &quot;二、Codex 的四种使用方式&quot;">​</a></h2><h3 id="方式-1-桌面-app-最推荐小白" tabindex="-1">方式 1：桌面 App（最推荐小白） <a class="header-anchor" href="#方式-1-桌面-app-最推荐小白" aria-label="Permalink to &quot;方式 1：桌面 App（最推荐小白）&quot;">​</a></h3><p><img src="https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800" alt="Codex 桌面 App"></p><ul><li>有可视化界面，操作一目了然</li><li>可以直接拖拽文件到工作区</li><li>实时查看 AI 的执行过程</li><li>权限管理直观清晰</li></ul><p><strong>适合人群</strong>：所有用户，尤其是零编程基础的新手</p><h3 id="方式-2-chatgpt-网页版" tabindex="-1">方式 2：ChatGPT 网页版 <a class="header-anchor" href="#方式-2-chatgpt-网页版" aria-label="Permalink to &quot;方式 2：ChatGPT 网页版&quot;">​</a></h3><p>在 <a href="https://chatgpt.com" target="_blank" rel="noreferrer">chatgpt.com</a> 中切换到 &quot;Advanced Search&quot; 或 &quot;Code Interpreter&quot; 模式。</p><ul><li>无需安装任何软件</li><li>随时随地可用</li><li>功能相对简单</li></ul><p><strong>适合人群</strong>：偶尔使用、不想安装软件的用户</p><h3 id="方式-3-命令行-cli" tabindex="-1">方式 3：命令行 CLI <a class="header-anchor" href="#方式-3-命令行-cli" aria-label="Permalink to &quot;方式 3：命令行 CLI&quot;">​</a></h3><p>通过终端直接使用 Codex，适合熟悉命令行的用户。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;帮我写一个排序程序&quot;</span></span></code></pre></div><p><strong>适合人群</strong>：开发者、运维人员</p><h3 id="方式-4-vs-code-插件" tabindex="-1">方式 4：VS Code 插件 <a class="header-anchor" href="#方式-4-vs-code-插件" aria-label="Permalink to &quot;方式 4：VS Code 插件&quot;">​</a></h3><p>在 VS Code 中安装 Codex 插件，直接在编辑器中使用。</p><p><strong>适合人群</strong>：已经在用 VS Code 的开发者</p><hr><h2 id="三、本节实操任务" tabindex="-1">三、本节实操任务 <a class="header-anchor" href="#三、本节实操任务" aria-label="Permalink to &quot;三、本节实操任务&quot;">​</a></h2><ol><li>登录你的 ChatGPT 账号</li><li>确认你当前使用的版本（免费/Plus/Pro）</li><li>尝试打开 ChatGPT 的 &quot;Advanced Search&quot; 模式</li><li>输入：&quot;你好，请做一个自我介绍&quot;</li></ol><blockquote><p>💡 <strong>提示</strong>：这一步只是为了让你熟悉界面，不需要理解太多技术细节。</p></blockquote><hr><h2 id="四、本节小结" tabindex="-1">四、本节小结 <a class="header-anchor" href="#四、本节小结" aria-label="Permalink to &quot;四、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>账号要求</td><td>ChatGPT 账号（免费版可用，推荐 Plus）</td></tr><tr><td>设备要求</td><td>macOS 12+ 或 Windows 10+</td></tr><tr><td>四种使用方式</td><td>桌面 App（推荐）、网页版、CLI、VS Code 插件</td></tr><tr><td>新手首选</td><td>桌面 App，操作简单直观</td></tr></tbody></table><hr><h2 id="五、下一步" tabindex="-1">五、下一步 <a class="header-anchor" href="#五、下一步" aria-label="Permalink to &quot;五、下一步&quot;">​</a></h2><p><a href="./lesson-5.html">→ 第 5 课：安装 Codex 桌面 App</a></p>',38)])])}const b=a(l,[["render",d]]);export{u as __pageData,b as default};
